    "/api/v1/arrivals/ping": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * The customer reports their position (geofence check-in and ETA)
         * @description Authenticated by the link token alone. Inside the check-in radius the job is checked in (auto check-in on) or flagged for staff to confirm (`confirm_needed`); outside it the ETA is stored and the crew is alerted once when it first reaches the prep time. Idempotent per `pingId`; a job that has arrived answers `already_arrived`. 401 ARRIVAL_LINK_INVALID, 410 ARRIVAL_LINK_EXPIRED, 409 ARRIVAL_NOT_CONFIGURED (the shop has no coordinates), 429 ARRIVAL_PING_TOO_FAST (Retry-After) or RATE_LIMITED. A browser page on another origin must be listed in ALLOWED_ORIGINS.
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody: {
                content: {
                    "application/json": {
                        /** @description The fix accuracy in metres; a fix wider than the check-in radius cannot prove arrival */
                        accuracyM?: number;
                        /** @description The customer tapped "I’m here" */
                        declared?: boolean;
                        /** @description The phone’s own ETA; otherwise the distance at 25 km/h */
                        etaMinutes?: number;
                        lat: number;
                        lng: number;
                        /** @description Your id for this ping; a repeat returns the first answer */
                        pingId?: string;
                        /** @description The check-in link token the shop issued for this appointment */
                        token: string;
                    };
                };
            };
            responses: {
                /** @description Default Response */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            /** @description Metres from the shop */
                            distanceM: number;
                            etaMinutes: number | null;
                            /** @description Plain text for the customer’s screen */
                            message: string;
                            /** @description The check-in radius from the arrival settings */
                            radiusM: number;
                            /** @enum {string} */
                            state: "outside" | "inconclusive" | "checked_in" | "confirm_needed" | "already_arrived" | "disabled";
                        };
                    };
                };
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
